from lib import *
S = SS('u153')
steps = [
    step("一个带 feature 的库 fmtx:default = [\"std-fmt\"],fast = [\"dep:itoa\"](启用就引入可选依赖 itoa),extra = []。库里用 cfg!(feature = \"…\") 在运行期报告自己编译时启用了什么,app 以 default-features = false 依赖它,再用自己的 feature 转发:不加任何 feature → 启用 [];--features use-std → [\"std-fmt\"];--features use-fast → [\"fast\"];use-fast,use-extra → [\"fast\", \"extra\"],并多出 \"extra 功能存在\" 一行(#[cfg(feature = \"extra\")] 的函数才存在)。", t=tl(S(1)), done=lidx(S(1), 'default-features = false', '--features use-std', '--features use-fast  ', 'use-fast,use-extra'), kv=KV([['default-features = false', '不启用任何 feature'], ['--features use-fast', 'fast(+ 可选依赖 itoa)'], ['--features use-fast,use-extra', 'fast + extra']], ['--features use-fast'])),
    step("可选依赖随 feature 才出现:cargo tree -e features --features use-fast 显示 app → fmtx → itoa(feature \"default\")→ itoa v1.0.18;不启用 fast 时,fmtx 的依赖树里没有 itoa(第五步的 cargo tree --no-default-features 只有 fmtx 自己),也就不会下载、编译它。", t=tl(S(2)), done=lidx(S(2), 'itoa feature', 'itoa v1.0.18'), kv=KV([['fast 启用', '依赖树里多一个 itoa'], ['fast 未启用', '没有 itoa']], ['fast 启用'])),
    step("feature 统一(unification):left 依赖 fmtx 并启用 fast,right 依赖 fmtx 并启用 extra,both 自己依赖 fmtx 却不启用任何 feature。结果 fmtx 只编译一份,启用的是并集 [\"fast\", \"extra\"] —— both 自己没要求,却也看到了;cargo tree -e features -i fmtx 显示 fast 是 left 启用的、extra 是 right 启用的。你的依赖会被别人启用的 feature 影响。", t=tl(S(3)), done=lidx(S(3), 'app 自己没有启用任何 feature', 'left 用到 fast'), mark=lidx(S(3), 'fmtx feature "extra"', 'fmtx feature "fast"'), kv=KV([['left 要 fast', ''], ['right 要 extra', ''], ['fmtx 实际', '[\"fast\", \"extra\"](并集,只编译一份)']], ['fmtx 实际'])),
    step("所以 feature 必须是「可加」的。互斥的 feature 会撞车:excl 的 backend-a 与 backend-b 同时启用时 compile_error!,xl 依赖的两个 crate 一个启用 backend-a、一个启用 backend-b,统一后同时启用,编译失败:error: backend-a 与 backend-b 不能同时启用。启用一个 feature 不应该让已有的功能失效或与别的 feature 冲突。", t=tl(S(4)), mark=lidx(S(4), 'error: backend-a'), kv=KV([['互斥 feature', '统一后同时启用 → 冲突'], ['设计原则', '启用 feature 只能增加功能']], ['互斥 feature'])),
    step("--no-default-features 对应 default-features = false:cargo tree 在 fmtx 上不带 feature 时只有 fmtx 自己;--features fast 时多出 └── itoa v1.0.18。默认 feature 会被使用者用 default-features = false 关掉,所以库作者要把「可选、重的」东西放在非默认 feature 里。", t=tl(S(5)), done=lidx(S(5), 'cargo tree --no-default-features', 'cargo tree --features fast'), kv=KV([['--no-default-features', '只有 fmtx'], ['--features fast', '+ itoa']], ['--features fast'])),
]
A = mkart('u153', 153, 'Rust,Cargo,feature,条件编译,真实验证,动画演示',
    '用自己写的库验证 Cargo feature:default / 可选依赖 dep:itoa / cfg!(feature) 报告编译内容;cargo tree -e features;feature 统一(left 要 fast、right 要 extra,fmtx 只编译一份并启用并集);互斥 feature 统一后 compile_error 冲突;--no-default-features 与可选依赖。',
    'Cargo feature 是条件编译和可选依赖的基础,却有一个出名的坑:feature 统一。这篇用自己写的小库逐个验证 default、可选依赖、转发,以及两个依赖启用不同 feature 时到底发生什么、互斥 feature 为什么不行。',
    [('并集', 'left 与 right 各启用一个 feature 时,fmtx 实际启用的 feature 集合'), ('1 份', 'fmtx 被编译的次数(feature 统一)'), ('compile_error', '互斥 feature 被统一后同时启用时的结果')],
    [('feature 与可选依赖', '<p>依赖版本的解析见<a href="rust-cargo-dependency-resolution.html">Cargo.toml 依赖解析</a>;条件编译的 cfg 更多用法见<a href="rust-cross-platform-paths.html">跨平台路径差异</a>。</p>'), ('可选依赖出现在哪', None), ('feature 统一', '<p>resolver = "2" 对 build-dependencies 与 dev-dependencies 的 feature 分开统一,本文没有验证。</p>'), ('互斥 feature', None), ('关掉默认 feature', '<p>工作区里统一管理见<a href="rust-workspace-dependencies.html">Workspace 依赖管理</a>。</p>')],
    steps, [ENV_U + '。库与应用是本地 path crate,itoa 来自 crates.io', '没有验证:resolver 1 与 2 的差别、dev-dependencies 对 feature 统一的影响、--all-features 的行为、feature 对编译时间与二进制体积的影响、cargo-hack 对 feature 组合的测试'], 'Feature Flag')
